    values: Readonly<Record<string, T>> | undefined,
    modelKey: string | undefined,
): { value: T; source: ModelKeyLookupSource } | undefined {
    if (!values) return undefined;

    for (const candidate of modelKeyLookupOrder(modelKey)) {
