Map raw projection rows to `Memory` values. On a v80 database a row whose stats tuple came back NULL means the one-row-per-memory invariant broke; that is corruption and must surface, never be silently filtered or healed from the frozen legacy columns.
export function memoryRowsFromQuery(db: Database, rows: readonly unknown[]): Memory[] {
    const out: Memory[] = [];
    const statsBacked = hasMemoryStatsTable(db);
    for (const row of rows) {
        if (isMemoryRow(row)) {
            out.push(toMemory(row));
            continue;
        }
        if (statsBacked && row !== null && typeof row === "object") {
            const candidate = row as Record<string, unknown>;
            if (typeof candidate.id === "number" && candidate.seenCount === null) {
                throw new MemoryStatsIntegrityError(candidate.id);
            }
        }
    }
    return out;
