Compute a deterministic call_id from the snapshot JSON. Stable for stable state; identical state across passes produces identical callID, which gives byte-identical wire shape on both cache-busting and defer passes. Format chosen to clearly distinguish from real provider-generated IDs: - Anthropic: `toolu_<24 base62 chars>` - OpenAI:    `call_<random>` - Synthetic: `mc_synthetic_todo_<16 hex chars>` Providers do not validate callID format — they only require matching IDs between tool_use and tool_result.
export function computeSyntheticCallId(stateJson: string): string {
    const hash = createHash("sha256").update(stateJson).digest("hex").slice(0, 16);
    return `${SYNTHETIC_CALL_ID_PREFIX}${hash}`;
}

