Whether a compartment should be archived (P5, not rendered). Anchor overlap extends P4 protection by up to G half-lives; with `o = 0` (v2.0 default) this reduces to `z >= Z4`.
export function shouldArchive(
    compartmentIndex: number,
    importance: number,
    budgetPressure: number,
    anchorOverlap = 0,
): boolean {
    const a = Math.max(compartmentIndex, 1) - 1;
    const imp = Math.max(1, Math.min(100, importance));
    const p = Math.max(budgetPressure, P_FLOOR);
    const o = Math.max(0, Math.min(1, anchorOverlap));

    const F = 2 ** ((imp - 50) / D);
    const H = (H50 * F) / p;
    const z = a / H;

    return z >= Z4 + G * o;
}

