Walk a rekey chain to its terminal identity. A cycle aborts with a bounded diagnostic instead of seeding split or looping authoritative history.
export function resolveTerminalIdentity(
    rekeyMap: ReadonlyMap<string, string>,
    identity: string,
): string {
    let current = identity;
    const seen = new Set<string>([current]);
    while (true) {
        const next = rekeyMap.get(current);
        if (next === undefined || next === current) return current;
        if (seen.has(next)) {
            throw new Error(
                `project identity rekey cycle detected: ${boundedIdentityList(seen)} -> ${next.slice(0, 120)}`,
            );
        }
        seen.add(next);
        current = next;
    }
}

