Compute OpenCode-equivalent pressure from a Pi usage payload + the effective context limit. Returns null when no usage is available. The formula intentionally omits output tokens — they're not part of the prefix sent to the next prompt, so they don't count against cacheable-prefix pressure. This matches `packages/plugin/src/hooks/magic-context/event-handler.ts:388-397` exactly: totalInputTokens = info.tokens.input + info.tokens.cache.read + info.tokens.cache.write
export function computePiPressure(
	usage: PiAssistantUsage | null,
	contextLimit: number,
): PiPressure | null {
	if (!usage) return null;
	const input = usage.input ?? 0;
	const cacheRead = usage.cacheRead ?? 0;
	const cacheWrite = usage.cacheWrite ?? 0;
	const inputTokens = input + cacheRead + cacheWrite;
	if (inputTokens === 0) return null;
	const percentage = contextLimit > 0 ? (inputTokens / contextLimit) * 100 : 0;
	return { inputTokens, percentage };
}

