    pub fn extend_from_slice(&mut self, bytes: &[u8]) -> Result<(), StreamClosed> {
        if bytes.len() > self.max_len.saturating_sub(self.body.len()) {
            return Err(StreamClosed);
        }
        self.body.extend_from_slice(bytes);
