Apply OpenCode's Permission.disabled rule: the last matching permission rule wins, and only a deny of the whole permission pattern disables it. Keeping this evaluator pure makes the findLast behavior testable without a live OpenCode server.
export function permissionDisabled(toolName: string, rules: readonly PermissionRule[]): boolean {
    let finalRule: PermissionRule | undefined;
    for (let index = rules.length - 1; index >= 0; index -= 1) {
        const rule = rules[index];
        if (rule && permissionNameMatches(rule.permission, toolName)) {
            finalRule = rule;
            break;
        }
    }
    return finalRule?.action === "deny" && finalRule.pattern === "*";
}

