Longest prefix of `text` whose UTF-8 encoding is at most `maxBytes`, never splitting a surrogate pair.
export function truncateUtf8Bytes(text: string, maxBytes: number): string {
    if (Buffer.byteLength(text, "utf8") <= maxBytes) return text;
    return text.slice(0, utf8PrefixEnd(text, maxBytes));
}

function utf8PrefixEnd(text: string, maxBytes: number, start = 0): number {
    let bytes = 0;
    let end = start;
    for (const char of text.slice(start)) {
        const charBytes = Buffer.byteLength(char, "utf8");
        if (bytes + charBytes > maxBytes) break;
        bytes += charBytes;
        end += char.length;
    }
    return end;
}

