Whether a TUI client is connected via a live notification socket. Now exact socket liveness (a registered WS sink), not a poll-drain timestamp. Pass `sessionId` (preferred) to ask whether a TUI is connected FOR THAT SESSION — this is what producers (`/ctx-status`, `/ctx-recomp`, the upgrade reminder) must use to decide dialog-vs-message, so a TUI on a different session in the same process does not misroute their delivery. A modern session-less sink is global-only; a legacy sink retains broad compatibility. Omit `sessionId` only for callers with no session context.
export function isTuiConnected(sessionId?: string): boolean {
    if (sinks.size === 0) return false;
    if (sessionId === undefined) return true;
    for (const sink of sinks) {
        if (sink.sessionId === sessionId) return true;
        if (sink.sessionId === undefined && sink.protocol !== 2) return true;
    }
    return false;
}

