lexicographic id, matching the legacy single-statement ordering (`ORDER BY time_created DESC, id DESC` limited to rows where `time_created < currentTime`). Returns null when: - The candidate list is empty - `currentMessageId` is not present in `times` - No candidate predates `currentMessageId` in OC time This helper is independent of any DB handle — the caller resolves the `times` map (typically via `getMessageTimesFromOpenCodeDb`) and passes it in. Splitting the lookup from the picking keeps `storage-tags.ts` free of any OpenCode-DB import.
export function pickNearestPriorOwner(
    candidates: readonly string[],
    currentMessageId: string,
    times: ReadonlyMap<string, number>,
): string | null {
    const currentTime = times.get(currentMessageId);
    if (typeof currentTime !== "number") return null;

    let best: { id: string; time: number } | null = null;
    for (const id of candidates) {
        const t = times.get(id);
        if (typeof t !== "number") continue;
        if (t > currentTime) continue;
        if (t === currentTime && id >= currentMessageId) continue;
        if (best === null || t > best.time || (t === best.time && id > best.id)) {
            best = { id, time: t };
