export function pruneExpiredUserMemoryCandidates(
    db: Database,
    ttlMs: number,
    now: number = Date.now(),
): number {
    const cutoff = now - ttlMs;
    const result = db
        .prepare("DELETE FROM user_memory_candidates WHERE created_at < ?")
        .run(cutoff);
    return Number(result.changes ?? 0);
}

