    domain: "memories" | "notes",
    run: () => Promise<void>,
): Promise<void> {
    const key = `${ensureContextStoreUuid(db)}\u0000${domain}`;
    const tail = mirrorDomainSyncChains.get(key) ?? Promise.resolve();
    const next = tail.then(run, run);
