        };
        let idx = rest
            .find(&token)
            .expect("token was located by find_substitution_token");
        out.push_str(&rest[..idx]);
        out.push_str(&resolve_token(&token, config_dir)?);
        rest = &rest[idx + token.len()..];
    }
