Inject a tool part into the latest replayable assistant message that has an ID. Idempotent on `callID` — if a part with the same `callID` already exists, this is a no-op so defer-pass replays produce byte-identical output. Returns the message ID where the part landed, or `null` if no eligible assistant message exists in the visible window. Assistant messages with an OpenCode `error` are skipped because provider serializers can omit failed or aborted assistants from the wire; anchoring a synthetic tool call there would make its replay disappear on subsequent passes.
export function injectToolPartIntoLatestAssistant(
    messages: MessageLike[],
    part: { callID: string },
): string | null {
    for (let index = messages.length - 1; index >= 0; index -= 1) {
        const message = messages[index];
        if (message.info.role !== "assistant") continue;
        if (typeof message.info.id !== "string") continue;
        if (!isReplayableAssistantAnchor(message)) continue;
        if (hasToolPartWithCallId(message, part.callID)) {
            // Already present — idempotent no-op for cache stability.
            return message.info.id;
        }
        message.parts.push(part);
        return message.info.id;
    }
    return null;
}

